import{_ as a,H as t,f as n,i as s}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"21 | 设计实战（一）：一个金融交易业务的自动化测试设计","description":"","frontmatter":{},"headers":[{"level":2,"title":"一个转账案例","slug":"一个转账案例","link":"#一个转账案例","children":[]},{"level":2,"title":"Job 数据建模","slug":"job-数据建模","link":"#job-数据建模","children":[]},{"level":2,"title":"Job 行为分解","slug":"job-行为分解","link":"#job-行为分解","children":[]},{"level":2,"title":"Job 扩展","slug":"job-扩展","link":"#job-扩展","children":[{"level":3,"title":"数据验证","slug":"数据验证","link":"#数据验证","children":[]},{"level":3,"title":"反例测试","slug":"反例测试","link":"#反例测试","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"自动化测试高手课/21｜设计实战（一）：一个金融交易业务的自动化测试设计.md","filePath":"自动化测试高手课/21｜设计实战（一）：一个金融交易业务的自动化测试设计.md","lastUpdated":1795563698000}'),i={name:"自动化测试高手课/21｜设计实战（一）：一个金融交易业务的自动化测试设计.md"};function p(o,e,l,b,E,r){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="_21-设计实战-一-一个金融交易业务的自动化测试设计" tabindex="-1">21 | 设计实战（一）：一个金融交易业务的自动化测试设计 <a class="header-anchor" href="#_21-设计实战-一-一个金融交易业务的自动化测试设计" aria-label="Permalink to &quot;21 | 设计实战（一）：一个金融交易业务的自动化测试设计&quot;">​</a></h1><p>你好，我是柳胜。</p><p>一提到金融业，可能你第一时间想到的就是钱。没错，存款、转账都是普通人最常接触的金融业务。不过在专业金融人士那里，钱的形态和流动方式也更加复杂，有交易、投资、期货、股票、基金等等金融模型。</p><p>从测试角度来看，金融业软件有两个特点：第一，对数据精准性要求非常高，不能出错，bug的成本极大；第二，软件的设计要求有很强的金融领域知识，也很复杂。</p><p>所以，金融行业对软件的交付质量要求高，对软件测试非常重视，自动化测试的投入也很大。而自动化测试设计的过程，其实也是对复杂业务梳理的过程。</p><p>挑战随之而来，用我们的 Job 模型，能不能让金融系统的复杂业务变得简单？今天我们就一起结合例子来看一看。</p><h2 id="一个转账案例" tabindex="-1">一个转账案例 <a class="header-anchor" href="#一个转账案例" aria-label="Permalink to &quot;一个转账案例&quot;">​</a></h2><p>我们来看后面这个转账案例。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/1.png" alt=""></a></p><p>这是一个类型为正例的测试案例。金融业测试里，要设计很多的测试案例，正例是那些预期能够正常完成业务的测试案例，而反例是由于违背了业务规则，预期无法成功完成业务的测试案例。</p><p>在我们的测试案例里，交易账户都是正常的状态，交易额度也在安全额度之内，预期结果是能够正常完成转账交易，所以类型是正例。</p><h2 id="job-数据建模" tabindex="-1">Job 数据建模 <a class="header-anchor" href="#job-数据建模" aria-label="Permalink to &quot;Job 数据建模&quot;">​</a></h2><p>了解了案例情况，我们想用 Job 模型来为它建模，该怎么做呢？</p><p>金融业务里最关键的要素就是数据，我们可以从数据角度来理一下测试案例。</p><p>这里的数据有账户数据，包括转出账户 A 和转入账户 B；还有交易数据，包括转账类型同行转账和转账金额 4000；另外，还有配置数据，单笔转账限额 5000 和交易超时时间 30 分钟等。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/2.png" alt=""></a></p><p>我们 Job 模型有三个传递数据的地方，分别是 JobInput、TestData 和 TestConfig。</p><p>Input 是从 Job 外部传递进来的数据，TestData 是 Job 自带的测试数据源，能够多组数据循环运行 Job，TestConfig 是 Job 会引用到的比较固定的配置数据。</p><p>想一想，账户数据和交易数据，需要放在 JobInput 里，还是 TestData 里呢？这个要看我们自动化测试整体设计。</p><p>如果我们每次测试运行都要创建新的测试账户，那转账 Job 就可以从 Input 里获得其他 Job 创建好的账户信息；反之，测试账户是存量的数据，那我们应该把它放在 TestData 里，实现“多份数据，一份代码”，这样才能提高转账 Job 的 ROI。</p><p>而单笔转账限额和交易超时时间，我们把它放在 TestConfig 里。表格更新如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/3.png" alt=""></a></p><p>Job 模型建模如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/4.png" alt=""></a></p><h2 id="job-行为分解" tabindex="-1">Job 行为分解 <a class="header-anchor" href="#job-行为分解" aria-label="Permalink to &quot;Job 行为分解&quot;">​</a></h2><p>数据研究完了，我们再来看梳理一下测试案例的操作步骤。</p><ol><li><p>登录系统</p></li><li><p>发起转账</p></li><li><p>验证转账4. 退出系统</p></li></ol><p>登录系统和退出系统这两个行为是通用的，为了提高 Job 的 ROI，我们可以把登录系统和退出系统独立出来 2 个 Job。而发起转账和验证这 2 个步骤，是作为 1 个 Job，还是分割成 2个 Job 呢。这取决于转账和验证的步骤复杂度，在刚开始时，我们不要过度工作 over work，可以把转账 + 验证先作为一个 Job。</p><p>这样的话，转账 Job 就分解成了 3 个子 Job：登录，转账和验证，退出。在 Web 上实现的话，我们选择用 Selenium 作为开发工具。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/5.png" alt=""></a></p><p>因为子 Job 继承了父 Job 的属性，现在 3 个子 Job 应该可以从 TestData 里拿到账户信息，登录 Job 用 A 账户进行登录，转账验证 Job 使用 A 账户给 B 账户转账 4000，退出 Job 退出 A账户。</p><p>现在自动化测试开发人员就可以用 Selenium 工具进行开发了！</p><h2 id="job-扩展" tabindex="-1">Job 扩展 <a class="header-anchor" href="#job-扩展" aria-label="Permalink to &quot;Job 扩展&quot;">​</a></h2><p>自动化测试开发人员开发出这 3 个 Job 后，就完成了转账自动化测试第一个版本。能实现跑起来的基础目标。</p><p>但要想让它稳定运行，我们还需要理清楚金融业务的关联性。比如，银行账户是有复杂的配置的，光账户状态就有几十种，比如时效、锁定、冻结、挂失等等。想要让转账测试运行成功，测试账户必须在正常的状态下，有转账的权限，而且还要有足够的余额等等这些条件。</p><p>这些都是转账业务成功运行的前提条件，如果不满足这些条件，直接开始运行转账 Job，可能会遇到各种“错误”。但这些“错误”是正常的预期，所以，诊断它们只会浪费你的时间。</p><h3 id="数据验证" tabindex="-1">数据验证 <a class="header-anchor" href="#数据验证" aria-label="Permalink to &quot;数据验证&quot;">​</a></h3><p>怎么办？为了保证转账 Job 的稳定运行，我们可以增加一个 ValidateJob 来验证数据。让转账 Job 的依赖指向 ValidateJob，如果 ValidateJob 运行通过，转账 Job 才会运行；否则，转账 Job 就不必运行。</p><p>ValidateJob 负责做数据验证，我们可以用Great Expectation 来完成这个验证。</p><p>Greate Expecation 是一个 Python 的数据验证框架，它支持多种数据源，内嵌规则引擎。为了让你直观了解它的使用过程，我为你准备了后面的流程图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/6.png" alt=""></a></p><p>我们的账户存在 MySQL 数据库里，可以在 greate_expectation.yaml 里配置数据库信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>datasource_yaml = r&quot;&quot;&quot;</span></span>
<span class="line"><span>name: my_mssql_datasource</span></span>
<span class="line"><span>class_name: Datasource</span></span>
<span class="line"><span>execution_engine:</span></span>
<span class="line"><span> class_name: SqlAlchemyExecutionEngine</span></span>
<span class="line"><span> connection_string: mssql+pyodbc://sheng.liu:Welcome1@&lt;​HOST&gt;:&lt;​PORT&gt;/&lt;​DATABASE&gt;?d</span></span>
<span class="line"><span> #要验证数据集是Account表</span></span>
<span class="line"><span> table: account</span></span></code></pre></div><p>然后，就可以在 Jupyter Notebook 里开发数据验证代码了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#验证账户信息</span></span>
<span class="line"><span>batch.load(greate_expectation.yaml)</span></span>
<span class="line"><span>#验证规则1:账户的State字段不为空，而且是Active状态</span></span>
<span class="line"><span>batch.expect_column_values_to_be_equal(&#39;State&#39;,&#39;Active&#39;)</span></span>
<span class="line"><span>#验证规则2:账户余额必须大于4000</span></span>
<span class="line"><span>batch.expect_column_values_greater_than(&quot;balance&quot;,4000)</span></span></code></pre></div><p>运行代码，Great Expectation 会从数据库里读取账户数据，进行数据验证，2 条规则都通过，整个 Job 运行成功，会产生下面的报告。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/7.png" alt=""></a></p><p>现在，我们把 Validate 数据 Job 添加到 Job 设计图里，更新如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/8.png" alt=""></a></p><p>这样，每次转账 Job 运行之前，都会先运行 Validate 数据 Job。只有数据都准备好了，转账Job 才会运行。在这个机制的保护下，转账 Job 的运行结果成功或失败，就更可信了。</p><h3 id="反例测试" tabindex="-1">反例测试 <a class="header-anchor" href="#反例测试" aria-label="Permalink to &quot;反例测试&quot;">​</a></h3><p>有了 ValidateJob 之后，我们可以考虑反例测试了。这里反例的逻辑是这样的：如果账户数据是异常的情况下，转账 Job 是会失败的，要是交易依然成功，那就是一个安全漏洞。</p><p>因为这种漏洞在金融业务里很可能带来巨大的经济损失，所以，在金融测试里，反例测试也是很重要的测试案例。</p><p>不同的反例条件，转账执行失败的结果也是不一样的，它们有一个对应关系。 我列了一个条件 - 结果表格，这样你能一目了然。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/9.png" alt=""></a></p><p>那自动化设计里，反例测试该怎么做？</p><p>你可能在第一时间想到的办法是，开发一个“转账 Job- 反例”，在这个反例 Job 里，把上面表格里的条件和结果，作为测试案例里的 Given 条件和 Then 预期输出。</p><p>这就引出了下一个问题，这个反例 Job 的数据从哪里来？其实，这种情况下，我们就可以利用Job 模型的 Input、Output 机制，让 ValidateJob 验证数据之后，把数据通过 Output 分发到转账正例和转账反例的 Job 中去。</p><p>Greate expectation 有一个 Action 的机制，根据规则匹配的结果，即可触发不同的 Action，配置文件如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>validation_operators:</span></span>
<span class="line"><span>   action_list_operator:</span></span>
<span class="line"><span>       class_name: ActionListValidationOperator</span></span>
<span class="line"><span>       action_list:</span></span>
<span class="line"><span>       - name: StateNotSatisfied # 状态不符合</span></span>
<span class="line"><span>         action:</span></span>
<span class="line"><span>           class_name: Output</span></span>
<span class="line"><span>           output: &quot;State not satisified&quot;</span></span>
<span class="line"><span>       - name: BalanceNotSatisfied # 余额不符合</span></span>
<span class="line"><span>         action:</span></span>
<span class="line"><span>           class_name: Output</span></span>
<span class="line"><span>           output: &quot;Balance not satisified&quot;</span></span></code></pre></div><p>现在我们再次重构 Job 设计树，就会得到下面这个设计结构。我们在跟转账正例 Job 平行的层级，再加上一个转账反例 Job。不难看出，正例和反例的数据都来自于一个 ValidateJob 的输出。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/10.png" alt=""></a></p><p>ValidateJob 专门负责账户的合法性验证，使用 Greate Expectation 工具，内嵌规则引擎，来加载和解析账户数据，并把账户数据分组通过 Output 输出。然后，转账的正例 Job 拿到合法的数据，反例 Job 拿到非法的数据。</p><p>我给你打个比方，帮助你理解一下这个工作原理。其实这个场景就像生产线，第一个工人只管生产螺丝钉，他很专业，可以生产不同型号的螺丝钉，他不需要知道谁会使用这些螺丝钉。他需要做的就是，做好螺丝钉后，就把他们放到传送带上；而第二个工人是造飞机的，他会从传送带上拿到飞机螺丝钉，然后开始自己的任务；第三个工人是造汽车的，他拿到汽车的螺丝钉也开启自己的任务了。</p><p>这样分工，每个工人都在干自己的专业工作，又通过传送带和其它工人完成了协作。放在软件设计上，就满足了高内聚，低耦合的设计原则。</p><p>好，咱们接着推演后续可能会怎样发展。如果哪一天，ValidateJob 里面越来越复杂了，一个人无法完成，需要分解给 10 个人去做。那么只需要保持 ValidateJob 接口不变，在ValidateJob 下面分解成 10 个子 Job 就可以。</p><p>就像生产线上，生产螺丝钉的人手不够用了，他是招 8 个人还是 10 个人，分成几个小组，这些都是这个小组内部的事，只要这一组，还是跟以前一样，对外提供不同型号的螺丝钉就可以了。</p><p>好，让我们回顾一下整个过程。我们从一个银行转账正例案例开始，向下细化成 3 个Selenium Job，又平行引入了数据验证 Job 和反例 Job。</p><p>到这里，你是不是对怎么应用 Job 模型更熟练了呢？我们利用这个模型，根据业务需要来扩展Job 树。具体扩展方向有两种，一种是向下去下钻，将测试场景分解细化；另一种是向上聚合抽象，把场景归类合并到一起，形成一个更大的场景。</p><p>最后，我们设计好了正例和反例 Job，就能聚合一起，生成一个转账的正反测试 Job。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/11.png" alt=""></a></p><p>其实这个 Job 树并不是“终点”，我们还可以根据业务的复杂度再进行细化。</p><p>金融系统里，数据验证是一个精细的工作，确保无误。在手机端、Web 端、API，甚至 DB 都要验证数据。根据这个需求，我们可以把转账 + 验证 Job，进一步分解，分解后的情况如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/21/12.png" alt=""></a></p><p>你可能还有疑惑，不知道要怎么判断，我们是否得到了一个足够细化的最终结果。其实判断起来也不难，终点就是业务逻辑梳理清楚后，这棵 Job 树的所有叶子结点，都明确了实现工具。这样，我们就可以推进分工，进入开发实现阶段了。</p><p>我在反例 Job 里，没有标注蓝色的实现工具，你可以考虑一下怎么细化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>在今天的例子里，我们通过 Job 树的设计，梳理了金融业务的数据流动和验证。而且由于金融业务的特殊性，尤其是对数据精准性的要求。我还带你认识了一款数据验证框架 GreateExpecation。它是基于 Python 语言的框架，能够从数据源里获得数据，进行规则验证，输出结果，而且在 Jupyter Notebook 里开发，交互性和效率都很好。</p><p>这整个的建模过程，经历了从整体到局部，从概要到细节的推演。其实，直到这棵 Job 树的叶子结点都有了选型好的工具、可开发的 Job，我们的交易案例设计才算清楚了，这也是业务梳理完毕的信号。</p><p>每一个叶子结点的 Job 就是一个开发任务，有接口、有数据、有配置，开发工作任务列表就出来了。而且，通过 Job 之间的依赖关系，我们也可以得出一个有优先顺序的开发执行计划，谁在前，谁在后。</p><p>今天这一讲，为了让表达更形象，我们沿用了树形图来推演设计。在实际工作中，我们可以把这个设计保存在 YAML 或 XML 文件里，方便去做验证和二次开发，我会在设计篇最后一讲说说这块的实现思路。</p><p>下一讲，我们会继续锻炼自动化设计思维，探索如何利用 Job 模型实现自动化部署管线的设计，敬请期待。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>你的项目里有没有涉及数据验证测试，你是怎么做的？</p><p>欢迎你在留言区和我交流互动，也推荐你把今天学的内容分享给更多同事、朋友。</p>`,85)])])}const A=a(i,[["render",p]]);export{h as __pageData,A as default};
